const seats=[{pos:'UTG',x:15,y:24},{pos:'UTG+1',x:35,y:9},{pos:'MP',x:65,y:9},{pos:'LJ',x:85,y:24},{pos:'HJ',x:94,y:52},{pos:'CO',x:80,y:79},{pos:'BTN',x:20,y:79},{pos:'SB',x:6,y:52},{pos:'BB · HERO',x:50,y:94}];
const stackBB=[100,85,125,62,110,73,90,48,100];
const bbValue=2;
export function simulatorPage(){return `<div class="simulator-page"><div class="simulator-controls" role="group" aria-label="Unidade dos stacks"><span>EXIBIR STACKS EM</span><div class="simulator-switch"><button type="button" data-stack-unit="bb" aria-pressed="true">BB</button><button type="button" data-stack-unit="chips" aria-pressed="false">FICHAS</button><button type="button" data-stack-unit="money" aria-pressed="false">MOEDA</button></div></div><section class="simulator-table-area" aria-label="Mesa de poker com nove jogadores"><div class="simulator-table"><div class="simulator-felt"><div class="simulator-board-label">BOARD</div><div class="simulator-board"><span>?</span><span>?</span><span>?</span><span>?</span><span>?</span></div><div class="simulator-pot">POTE · 0 BB</div></div></div>${seats.map((seat,i)=>`<div class="simulator-seat ${i===8?'simulator-hero':''}" style="--seat-x:${seat.x}%;--seat-y:${seat.y}%"><span class="simulator-seat-name">${i===8?'HERÓI':'JOGADOR '+(i+1)}</span><strong class="simulator-seat-position">${seat.pos}</strong><span class="simulator-stack" data-stack-bb="${stackBB[i]}">${stackBB[i]} BB</span></div>`).join('')}</section><div class="simulator-legend">9 JOGADORES · BLINDS 1 / 2 · STACKS ILUSTRATIVOS</div><div class="simulator-pokerinno"><strong>POKERINNO EXPLICA</strong><p>Observe as posições e os stacks. Alterne entre BB, fichas e moeda para visualizar a mesma mesa em unidades diferentes. Esta é a tela inicial do simulador; as decisões de jogo ainda não estão habilitadas.</p></div></div>`}
export function setupSimulator(root){const page=root.querySelector('.simulator-page');if(!page)return;page.querySelectorAll('[data-stack-unit]').forEach(button=>button.addEventListener('click',()=>{const unit=button.dataset.stackUnit;page.querySelectorAll('[data-stack-unit]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));page.querySelectorAll('[data-stack-bb]').forEach(el=>{const bb=Number(el.dataset.stackBb);el.textContent=unit==='bb'?bb+' BB':unit==='chips'?(bb*bbValue).toLocaleString('pt-BR')+' FICHAS':(bb*bbValue).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})})}))}
